#ifndef CSM_MSG_H
#define CSM_MSG_H

#include <stdio.h>

struct catalog_entry {
	const char *key;
	const char *text;
};

struct catalog_lang {
	const char *code;
	const struct catalog_entry *entries;
	const char *help;
};

/* Generated from lang/ and help/ by tools/embed.sh; ends with code NULL. */
extern const struct catalog_lang catalog_langs[];

void msg_init(void);
const char *msg(const char *key);
const char *msg_help(const char *name, size_t *len);
void msg_print(FILE *fp, const char *key, ...);
void msg_error(const char *key, ...);
char *msg_text(const char *key, ...);

#endif
